import {db,ui,persist,rerender,navigate,esc,money,num,pct,icon,formatDate,timeLabel,relative,teamAccounts,teamTypes,teamUsers,modal,closeModal,toast,resetDemo,validateUserIdentity} from './core.js';
import {renderAnalytics,bindAnalytics} from './analytics.js';
import {renderSettings,bindSettings,renderSync,bindSync,runSync} from './settings.js';
import {renderAccounts,bindAccounts,openAdd,openAccount} from './accounts.js';

for(const k of ['meta','rollup']){if(db.sync[k].status==='running'){db.sync[k].status='error';db.sync[k].error='Демонстрационная загрузка прервана закрытием страницы. Повторите обновление.';}}
const roleNames={admin:'Администратор',lead:'Тимлид',buyer:'Байер'};
const pageNames={analytics:'Аналитика',accounts:'Кабинеты',settings:'Настройки команды',sync:'Синхронизация'};
function teamName(){return db.teamProfiles?.[db.teamId]?.name||'Команда Alpha';}
function user(){return teamUsers().find(x=>x.id===db.currentUserId)||teamUsers()[0];}
function initials(name){return String(name).split(' ').slice(0,2).map(x=>x[0]).join('');}
function sourceHealth(k){const s=db.sync[k],cfg=db.sync.config;if(s.status==='running')return'running';if(cfg.paused)return'paused';if(s.status==='error')return'error';if(!s.lastSuccess||Date.now()-s.lastSuccess>cfg.staleAfter*60000)return'stale';return'fresh';}
function health(){const a=['meta','rollup'].map(sourceHealth);return a.includes('error')?'error':a.includes('stale')?'stale':a.includes('running')?'running':a.includes('paused')?'paused':'fresh';}
function freshness(){const h=health();const labels={error:'Ошибка обновления',stale:'Данные устарели',running:'Обновляем данные…',paused:'Обновления на паузе',fresh:'Обновлено '+relative(Math.min(db.sync.meta.lastSuccess,db.sync.rollup.lastSuccess))};return `<button class="global-status ${h}" data-freshness title="Актуальность двух источников AIO"><span class="dot"></span><span>${labels[h]}</span>${icon('down')}</button>`;}
function nav(route,label,glyph,count=''){return `<a href="#${route}" class="nav-link ${ui.route===route?'active':''}" ${ui.route===route?'aria-current="page"':''}>${icon(glyph)}<span>${label}</span>${count!==''?'<span class="nav-count">'+count+'</span>':''}</a>`;}
function shell(content){const u=user();const h=health();return `<div class="shell"><aside class="sidebar"><a class="brand" href="#analytics"><span class="brand-mark">${icon('box')}</span>Account Lab<sup>β</sup></a><div class="team-block"><span class="team-icon">DV</span><div><strong>${esc(teamName())}</strong><small>DEUS VISION · WORKSPACE</small></div></div><div class="nav-label">Рабочее пространство</div><nav>${nav('analytics','Аналитика','chart')}${nav('accounts','Кабинеты','accounts',teamAccounts().length)}${nav('settings','Настройки команды','settings')}</nav><div class="nav-label" style="margin-top:25px">Система</div><nav>${nav('sync','Синхронизация','sync',h==='error'?'!':'')}</nav><div class="sidebar-bottom"><div class="prototype-card"><div class="eyebrow">Интерактивный прототип</div><p>Моковые данные · v0.1</p><button data-demo>Сценарии и роли ${icon('arrow')}</button></div><button class="profile-button" data-profile><span class="avatar">${esc(initials(u.username))}</span><span><strong>${esc(u.username)}</strong><small>${roleNames[db.role]}</small></span>${icon('dots')}</button></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><span>Рабочее пространство</span>${icon('chevron')}<span>${pageNames[ui.route]||'Аналитика'}</span></div><a class="mobile-brand" href="#analytics"><span class="brand-mark">${icon('box')}</span>Account Lab</a><div class="top-tools">${freshness()}<button class="btn-icon top-help" data-help aria-label="О прототипе">${icon('help')}</button></div></header><main class="content">${h==='error'||h==='stale'?`<div class="sync-strip">${icon('warning')}<span>${h==='error'?'Последняя попытка загрузки завершилась ошибкой. Показаны ранее полученные данные.':'Данные не обновлялись дольше заданного интервала актуальности.'}</span><button class="btn btn-sm" data-go-sync>Подробнее ${icon('arrow')}</button></div>`:''}${content}</main></div><nav class="mobile-nav" aria-label="Основная навигация">${[['analytics','Аналитика','chart'],['accounts','Кабинеты','accounts'],['settings','Настройки','settings'],['sync','Синхронизация','sync']].map(([r,n,i])=>`<a href="#${r}" class="${ui.route===r?'active':''}">${icon(i)}${n}</a>`).join('')}<button data-demo>${icon('dots')}Демо</button></nav></div>`;}
function showFreshness(){modal('Актуальность данных',`<div class="stack">${[['meta','Meta · Ad Accounts','Raw Spend и статусы'],['rollup','Roll Up Report','Spend, Revenue и Profit']].map(([k,n,sub])=>{const s=db.sync[k],h=sourceHealth(k);return `<div class="panel"><div class="panel-head"><div><h3>${n}</h3><p>${sub}</p></div><span class="badge ${h==='fresh'?'badge-green':h==='error'?'badge-red':'badge-amber'}">${{fresh:'Актуально',error:'Ошибка',stale:'Устарело',running:'Загрузка',paused:'На паузе'}[h]}</span></div><div class="panel-body"><div class="row-between"><span class="muted">Успешная загрузка</span><strong>${timeLabel(s.lastSuccess)}</strong></div><div class="row-between" style="margin-top:8px"><span class="muted">Последняя попытка</span><span>${timeLabel(s.lastAttempt)}</span></div>${h==='error'?`<div class="notice error" style="margin-top:14px">${esc(s.error||'Ошибка API')}</div>`:''}</div></div>`}).join('')}<p class="small muted">Дата успешной загрузки меняется только после получения данных. В прототипе обновления имитируются.</p></div>`,`<button class="btn" data-modal-close>Закрыть</button><button class="btn btn-primary" id="freshness-details">Перейти к синхронизации ${icon('arrow')}</button>`);document.querySelector('#freshness-details').onclick=()=>{closeModal();navigate('sync');};}
function demoDialog(){modal('Сценарии прототипа',`<div class="stack"><div class="notice">Изменения сохраняются в этом браузере. AIO не подключён: все кабинеты, пользователи и загрузки демонстрационные.</div><label class="field">Демонстрационная команда<select id="demo-team"><option value="alpha" ${db.teamId==='alpha'?'selected':''}>Команда Alpha · 5 типов</option><option value="beta" ${db.teamId==='beta'?'selected':''}>Команда Beta · отдельные данные</option></select></label><label class="field">Посмотреть интерфейс в роли<select id="demo-role"><option value="admin" ${db.role==='admin'?'selected':''}>Администратор системы</option><option value="lead" ${db.role==='lead'?'selected':''}>Тимлид</option><option value="buyer" ${db.role==='buyer'?'selected':''}>Байер</option></select></label><div class="demo-choices"><button class="demo-choice" id="demo-mobile">${icon('accounts')}<h3>Мобильный вид</h3><p>Проверить экран шириной 390 px</p></button><button class="demo-choice" id="demo-login">${icon('logout')}<h3>Экран входа</h3><p>Посмотреть авторизацию</p></button></div><p class="small muted">Переключение команд доступно здесь только для демонстрации. В рабочем продукте пользователь видит свою команду.</p></div>`,`<button class="btn btn-ghost" id="demo-reset">Сбросить демо</button><button class="btn btn-primary" id="demo-apply">Применить</button>`);document.querySelector('#demo-apply').onclick=()=>{db.teamId=document.querySelector('#demo-team').value;db.role=document.querySelector('#demo-role').value;db.currentUserId=teamUsers().find(x=>x.role===db.role&&x.status==='active')?.id||teamUsers().find(x=>x.status==='active')?.id;ui.filters={buyer:'all',type:'all',status:'all',period:'month',geo:'all',search:''};ui.accountPage=1;ui.selected.clear();persist();closeModal();rerender();toast('Демонстрационная роль изменена');};document.querySelector('#demo-mobile').onclick=()=>{closeModal();document.body.classList.toggle('mobile-preview');const exists=document.querySelector('.preview-exit');if(exists)exists.remove();else{const b=document.createElement('button');b.className='btn btn-primary preview-exit';b.innerHTML=icon('close')+' Выйти из мобильного вида';b.onclick=()=>{document.body.classList.remove('mobile-preview');b.remove();};document.body.append(b);}};document.querySelector('#demo-login').onclick=()=>{closeModal();navigate('login');};document.querySelector('#demo-reset').onclick=()=>{modal('Сбросить демонстрационные данные?',`<p>Созданные в этом браузере кабинеты, типы и приглашения будут заменены исходным набором. Реальные данные не затрагиваются.</p>`,`<button class="btn" data-modal-close>Отмена</button><button class="btn btn-primary" id="confirm-reset">Сбросить</button>`);document.querySelector('#confirm-reset').onclick=()=>{closeModal();resetDemo();toast('Исходные данные восстановлены');};};}
function profileDialog(){
 const u=user();
 modal('Профиль',`<form id="profile-form" class="stack"><div class="form-grid"><label class="field">Username<input name="username" value="${esc(u.username)}" autocomplete="username" required minlength="3" maxlength="40" pattern="[a-zA-Z0-9_.\\-]+"></label><label class="field">Email<input name="email" type="email" value="${esc(u.email)}" autocomplete="email" required></label><label class="field">Команда<input disabled value="${esc(teamName())}"></label><label class="field">Роль<input disabled value="${roleNames[db.role]}"></label><label class="field full">Пользователь AIO<input disabled value="${esc(u.aio)}"></label></div><div id="profile-error" class="form-error" role="alert" hidden></div></form>`,`<button class="btn btn-ghost" id="logout-demo">${icon('logout')} Выйти</button><button class="btn" data-modal-close>Отмена</button><button class="btn btn-primary" type="submit" form="profile-form">Сохранить изменения</button>`);
 document.querySelector('#profile-form').onsubmit=e=>{
  e.preventDefault();
  const data=new FormData(e.currentTarget),username=String(data.get('username')||'').trim(),email=String(data.get('email')||'').trim().toLowerCase();
  const error=validateUserIdentity(username,email,u.id);
  if(error){const node=document.querySelector('#profile-error');node.textContent=error;node.hidden=false;return;}
  Object.assign(u,{username,email});delete u.name;
  persist();closeModal();rerender();toast('Профиль обновлён');
 };
 document.querySelector('#logout-demo').onclick=()=>{closeModal();navigate('login');};
}

function help(){modal('Account Lab',`<div class="stack"><p>Рабочее пространство для сравнения типов рекламных кабинетов и результатов их использования.</p><div class="notice">Это кликабельный прототип на моковых данных. Все изменения остаются в вашем браузере; реальных запросов и приглашений нет.</div><div><h3>Что можно попробовать</h3><p style="margin-top:8px">Сравнить типы и байеров, открыть кабинет из графика, добавить кабинеты списком, изменить цену типа, переназначить байера и проверить ошибку синхронизации.</p></div></div>`,`<button class="btn btn-primary" data-modal-close>Понятно</button>`);}
function auth(){const parts=ui.route.split('/');const invite=parts[0]==='invite';const u=invite?db.users.find(x=>x.id===parts[1]):null;const token=parts[2];const valid=u&&u.status==='invited'&&(!u.expires||u.expires>Date.now())&&(!u.inviteToken||u.inviteToken===token)&&(!u.token||u.token===token);let body;
if(invite&&!valid){body=`<span class="brand-mark">${icon('link')}</span><h1>Приглашение недоступно</h1><p>Ссылка истекла, отозвана или уже использована. Попросите администратора выпустить новое приглашение.</p><button class="btn btn-primary" id="auth-back-app">Вернуться в прототип</button>`;}
else if(invite){body=`<span class="brand-mark">${icon('users')}</span><h1>Добро пожаловать, ${esc(u.username)}</h1><p>${esc(db.teamProfiles?.[u.team]?.name||'Команда')} · ${roleNames[u.role]}</p><form id="auth-form"><div class="field"><label>Email</label><input disabled value="${esc(u.email)}"></div><div class="field"><label>Username · AIO</label><input disabled value="${esc(u.username)} · ${esc(u.aio)}"></div><div class="field"><label for="auth-pass">Придумайте демо-пароль</label><input id="auth-pass" type="password" autocomplete="new-password" minlength="8" required placeholder="Не менее 8 символов"></div><div class="field"><label for="auth-confirm">Повторите пароль</label><input id="auth-confirm" type="password" autocomplete="new-password" minlength="8" required></div><div class="auth-error" id="auth-error" hidden></div><button class="btn btn-primary">Активировать приглашение ${icon('arrow')}</button></form><div class="notice">Демонстрация: пароль не сохраняется. Не используйте рабочий пароль.</div><div class="auth-back"><a href="#settings" class="link-button">Вернуться в прототип</a></div>`;}
else {body=`<span class="brand-mark">${icon('box')}</span><h1>Войти в Account Lab</h1><p>Аналитика кабинетов вашей команды.</p><form id="auth-form"><div class="field"><label for="auth-user">Email или username</label><input id="auth-user" autocomplete="username" value="${esc(user().username)}" required placeholder="name@company.com"></div><div class="field"><label for="auth-pass">Пароль</label><input id="auth-pass" type="password" autocomplete="current-password" required placeholder="Любой демо-пароль"></div><div class="auth-error" id="auth-error" hidden></div><button class="btn btn-primary">Войти ${icon('arrow')}</button></form><div class="auth-back"><button class="link-button" id="demo-quick-login">Войти как администратор демо</button></div><div class="notice">Прототип без сервера. Используйте любой демо-пароль — он не сохраняется.</div>`;}
return `<div class="auth-layout"><div class="auth-art"><div class="brand"><span class="brand-mark">${icon('box')}</span>Account Lab</div><div class="auth-story"><span class="badge">DEUS VISION</span><h1>Каждый кабинет.<br>Понятный результат.</h1><p>Стоимость, открут и прибыль — в одном пространстве. Найдите типы кабинетов, которые работают для вашей команды.</p></div><div class="auth-art-footer">Интерактивный прототип · 2026</div></div><div class="auth-main"><div class="auth-card">${body}</div></div></div>`;}
function bindAuth(){const parts=ui.route.split('/');document.querySelector('#auth-back-app')?.addEventListener('click',()=>navigate('settings'));document.querySelector('#demo-quick-login')?.addEventListener('click',()=>{db.teamId='alpha';db.currentUserId='u1';db.role='admin';persist();navigate('analytics');});document.querySelector('#auth-form')?.addEventListener('submit',e=>{e.preventDefault();if(parts[0]==='invite'){const u=db.users.find(x=>x.id===parts[1]);if(!u||u.status!=='invited'||u.expires<Date.now()||u.token!==parts[2]){rerender();return;}if(document.querySelector('#auth-pass').value!==document.querySelector('#auth-confirm').value){const err=document.querySelector('#auth-error');err.hidden=false;err.textContent='Пароли не совпадают';return;}u.status='active';u.activatedAt=Date.now();db.teamId=u.team;db.currentUserId=u.id;db.role=u.role;persist();navigate('analytics');toast('Демонстрационное приглашение активировано');}else{const value=document.querySelector('#auth-user').value.trim().toLowerCase();const u=db.users.find(x=>(x.username.toLowerCase()===value||x.email.toLowerCase()===value)&&x.status==='active');if(!u){const err=document.querySelector('#auth-error');err.hidden=false;err.textContent='Нет активного демонстрационного пользователя с таким email или username';return;}db.teamId=u.team;db.currentUserId=u.id;db.role=u.role;persist();navigate('analytics');toast('Демо-вход выполнен');}});}
function render(){ui.route=location.hash.slice(1)||'login';if(ui.route.startsWith('invite')||ui.route==='login'){document.title=(ui.route==='login'?'Вход':'Активация')+' · Account Lab';document.getElementById('app').innerHTML=auth();bindAuth();return;}if(!pageNames[ui.route])ui.route='analytics';const view=ui.route==='analytics'?renderAnalytics():ui.route==='accounts'?renderAccounts():ui.route==='settings'?renderSettings(ui.settingsTab):renderSync();document.getElementById('app').innerHTML=shell(view);if(ui.route==='analytics')bindAnalytics();if(ui.route==='accounts')bindAccounts();if(ui.route==='settings')bindSettings();if(ui.route==='sync')bindSync();document.title=(pageNames[ui.route]||'Account Lab')+' · Account Lab';}
document.addEventListener('click',e=>{if(e.target.closest('[data-demo]'))demoDialog();if(e.target.closest('[data-profile]'))profileDialog();if(e.target.closest('[data-freshness]'))showFreshness();if(e.target.closest('[data-go-sync]'))navigate('sync');if(e.target.closest('[data-help]'))help();if(e.target.closest('[data-add]'))openAdd(e.target.closest('[data-add]').dataset.add||'single');});
window.addEventListener('hashchange',()=>{closeModal();window.scrollTo(0,0);render();});window.addEventListener('app:render',render);
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();navigate('accounts');setTimeout(()=>document.querySelector('#account-search')?.focus(),50);}});
setInterval(()=>{const el=document.querySelector('[data-freshness]');if(el){const t=document.createElement('div');t.innerHTML=freshness();el.replaceWith(t.firstElementChild);}},30000);
render();
